const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const startDate = '2016-08-01';
  const endDate = '2018-02-28';

  // Define country geometries
  const gaul = ee.FeatureCollection('FAO/GAUL/2015/level0');
  const cambodiaGeom = gaul.filter(ee.Filter.eq('ADM0_NAME', 'Cambodia')).geometry();
  const vietnamGeom = gaul.filter(ee.Filter.eq('ADM0_NAME', 'Vietnam')).geometry();

  // Validate geometries
  if (cambodiaGeom.area().getInfo() === 0 || vietnamGeom.area().getInfo() === 0) {
    console.log("Error: Could not retrieve valid geometries for Cambodia or Vietnam.");
    console.log("C3");
    return;
  }

  // 2. Data Acquisition
  // Use MODIS Collection 6.1 active fire detections
  const firesCollection = ee.FeatureCollection('MODIS/006/MCD14ML')
    .filterDate(startDate, endDate);

  // Check if the initial fire collection is empty
  const initialFiresCount = await firesCollection.size().getInfo();
  if (initialFiresCount === 0) {
    console.log(`No fire detections found in the global collection for the period ${startDate} to ${endDate}.`);
    console.log("C1");
    return;
  }
  console.log(`Total fire detections in global collection: ${initialFiresCount}`);

  // 3. Filter fire detections by country
  const cambodiaFires = firesCollection.filterBounds(cambodiaGeom);
  const vietnamFires = firesCollection.filterBounds(vietnamGeom);

  // Get the number of fire detections for each country
  const cambodiaFiresCount = await cambodiaFires.size().getInfo();
  const vietnamFiresCount = await vietnamFires.size().getInfo();

  // 4. Validation & Final Answer
  console.log(`Cambodia active fire detections: ${cambodiaFiresCount}`);
  console.log(`Vietnam active fire detections: ${vietnamFiresCount}`);

  if (cambodiaFiresCount === null || vietnamFiresCount === null ||
      typeof cambodiaFiresCount !== 'number' || typeof vietnamFiresCount !== 'number') {
    console.log("Error: Fire detection counts are invalid (null or not a number).");
    console.log("C3");
  } else if (cambodiaFiresCount === 0 && vietnamFiresCount === 0) {
    console.log("No active fire detections found for either country.");
    console.log("C2"); // No valid pixels/detections for the specified regions after filtering
  } else if (cambodiaFiresCount > vietnamFiresCount) {
    console.log("A");
  } else {
    console.log("B");
  }
}

